"""Independently worked answers for BC Science Chapter 3 Forces.

IDs follow content/bc-forces-questions.json. Preserve source misprints in the
question crops and explain corrections and missing data in the answers.
"""
from bc_kinematics_answers import paragraphs as p, parts, table, graph

ANSWERS = {}
def answer(n, body):
    assert f'q-{n}' not in ANSWERS
    ANSWERS[f'q-{n}'] = body

answer(1,p('Separately, the book usually lands first because air resistance has a much larger effect relative to the paper’s weight. With the paper resting entirely on top of the book, the book shields it from most air resistance, so they fall together.','With negligible air resistance, objects released from the same height with the same initial vertical velocity have the same acceleration g, regardless of mass.'))
answer(2,p('F<sub>g</sub> = mg = (90)(9.81) = 882.9 N ≈ <strong>8.8 × 10² N downward</strong>. Weight is the gravitational force, so the two requested quantities are the same.'))
answer(3,p('m = F<sub>g</sub>/g = 637/9.81 = <strong>64.9 kg</strong> (about 65 kg).'))
answer(4,p('g<sub>Moon</sub> = F<sub>g</sub>/m = 127.5/75 = <strong>1.7 N/kg</strong>, equivalent to 1.7 m/s².'))
answer(5,p('For fixed masses, F<sub>g</sub> = GMm/r², so F′/F = (r/r′)².')+parts('Double r: <strong>F/4</strong>.','Triple r: <strong>F/9</strong>.','Halve r: <strong>4F</strong>.','Reduce r to one-third: <strong>9F</strong>.'))
answer(6,p('Use F<sub>g</sub> = GMm/r², with masses in kilograms and centre-to-centre distance in metres.')+parts('Earth: (6.67 × 10⁻¹¹)(5.98 × 10²⁴)(100.0)/(6.38 × 10⁶)² = <strong>980 N</strong>, toward Earth’s centre.','Moon: (6.67 × 10⁻¹¹)(7.35 × 10²²)(100.0)/(1.74 × 10⁶)² = <strong>162 N</strong>, toward the Moon’s centre.','Golf balls: m = 0.046 kg, r = 0.10 m. F = (6.67 × 10⁻¹¹)(0.046)²/(0.10)² = <strong>1.4 × 10⁻¹¹ N</strong>. Each ball attracts the other with this magnitude.'))
answer(7,p('Expected observation: the two steel balls hit approximately together. Neglecting drag, a = F<sub>g</sub>/m = mg/m = g, so increasing mass increases gravitational force but does not change free-fall acceleration. Report your actual observations and experimental uncertainty.'))
answer(8,parts('In air, the steel ball normally lands first. Tissue paper has a large area and experiences a large drag force relative to its weight.','In a vacuum, both fall together because air resistance is absent and both accelerate at g.'))
answer(9,p('The horizontally launched and dropped balls land at approximately the same time, provided they start at the same height with zero initial vertical velocity. Their vertical motion is y = ½gt² downward. Horizontal velocity does not alter that vertical motion in the ideal model.'))
answer(10,p('In the Moon’s negligible atmosphere, both steel balls, tissue and ball, and coin and feather released together fall together. The horizontally launched and dropped balls also land together. All accelerate more slowly than on Earth.','For the same height and g<sub>Moon</sub> ≈ g<sub>Earth</sub>/6, t = √(2h/g) is about <strong>√6 ≈ 2.45 times longer</strong>.'))
answer(11,parts('Plot <strong>F<sub>g</sub> versus 1/r²</strong>. This produces a straight line through the origin; F versus 1/r is still curved.','With r in megametres, F<sub>g</sub> ≈ (398 N·Mm²)/r², since 9.81 × 6.37² = 398.06. Equivalently, F<sub>g</sub> ≈ (3.98 × 10¹⁴ N·m²)/r² with r in metres.')+graph('Gravity on a 1 kg mass versus distance', [('F = 9.81(6.37/r)²',[(6.37*i/20,9.81/(i/20)**2) for i in range(20,101)],'#096a70')],32,0,10,xlabel='Distance from Earth’s centre (Mm)',ylabel='Force (N)',xticks=[0,6.37,12.74,19.11,25.48,31.85],yticks=[0,2,4,6,8,10])+graph('Linearized inverse-square relationship', [('F = 398/r²',[(0,0),(1/6.37**2,9.81)],'#096a70')],.025,0,10,xlabel='1/r² (Mm⁻²)',ylabel='Force (N)',xticks=[0,.005,.01,.015,.02,.025],yticks=[0,2,4,6,8,10]))
answer(12,parts('Set F/F<sub>surface</sub> = ½ = (R/r)². Thus <strong>r = R√2 = 9.01 Mm from Earth’s centre</strong>, about 2.64 Mm above the surface.','At r = 10R, F = 9.81/10² = <strong>0.0981 N</strong>.'))
answer(13,p('A “600 N person” is already described by their weight. The gravitational force is <strong>600 N downward</strong>.'))
answer(14,p('F = GM<sub>Sun</sub>M<sub>Earth</sub>/r². With Earth’s mass and separation unchanged, tripling the Sun’s mass <strong>triples the force</strong>.'))
answer(15,parts('Earth: F<sub>g</sub> = (80)(9.81) = 784.8 N ≈ <strong>7.8 × 10² N downward</strong>.','Moon, using the stated g = 1.7 m/s²: F<sub>g</sub> = (80)(1.7) = <strong>1.4 × 10² N downward</strong> (136 N before rounding).'))
answer(16,p('Compare each case with F = GMm/d².')+parts('Double only M: <strong>2F</strong>.','Double only m: <strong>2F</strong>.','Double both masses: <strong>4F</strong>.','Double both masses and d: 4F/2² = <strong>F</strong>, unchanged.'))
answer(17,p('F<sub>g</sub> = (6.67 × 10⁻¹¹)(5.98 × 10²⁴)(70.0)/(6.38 × 10⁶)² = <strong>686 N downward</strong>.','Check: mg = (70.0)(9.81) = 686.7 N ≈ <strong>687 N</strong>. The small difference comes from rounded Earth data, which give g ≈ 9.799 N/kg.'))
answer(18,parts('At 2.0 m: F = (6.67 × 10⁻¹¹)(75)(60.0)/2.0² = <strong>7.5 × 10⁻⁸ N</strong>.','At 1.0 m: F = (6.67 × 10⁻¹¹)(75)(60.0)/1.0² = <strong>3.0 × 10⁻⁷ N</strong>, four times greater.')+p('The simple calculation treats the stated distances as centre-to-centre distances and the people as point masses. Each person experiences the same force magnitude toward the other.'))
answer(19,p('F<sub>g</sub> = (6.67 × 10⁻¹¹)(7.34 × 10²²)(70.0)/(1.74 × 10⁶)² = <strong>113 N</strong>, toward the Moon’s centre.'))
answer(20,p('F<sub>g</sub> = (6.67 × 10⁻¹¹)(6.37 × 10²³)(70.0)/(3.43 × 10⁶)² = <strong>253 N</strong>, toward Mars’s centre.'))
answer(21,p('F<sub>g</sub> = (6.67 × 10⁻¹¹)(1.90 × 10²⁷)(70.0)/(7.18 × 10⁷)² = <strong>1.72 × 10³ N</strong>, toward Jupiter’s centre.'))
answer(22,p('Repeated poking compacts the rice around the pencil. The tightly packed grains press against the pencil, increasing the normal forces and available static friction. When the upward frictional force transmitted through the pencil is large enough to support the rice and jar, you can lift them together.'))
answer(23,p('For a horizontal push on a level floor with no vertical acceleration, N = F<sub>g</sub> = 450 N. At steady speed, the push balances kinetic friction.','F<sub>push</sub> = μ<sub>k</sub>N = (0.30)(450) = 135 N ≈ <strong>1.4 × 10² N</strong>.'))
answer(24,p('Constant speed means zero net horizontal force. The total resisting friction is therefore <strong>30 N opposite the motion</strong>.'))
answer(25,parts('N = mg = (10)(9.81) = 98.1 N. Maximum static friction is μ<sub>s</sub>N = (0.30)(98.1) = <strong>29.4 N</strong>. A horizontal push must exceed this threshold to initiate sliding (about 29 N).','Once sliding, F = μ<sub>k</sub>N = (0.25)(98.1) = <strong>24.5 N</strong> (about 25 N) to maintain constant speed.'))
answer(26,p('Assuming the stated resisting force is modeled as kinetic friction on a level road, N = mg = (2000)(9.81) = 19 620 N.','μ<sub>k</sub> = F<sub>fr</sub>/N = (1.57 × 10⁴)/19 620 = <strong>0.800</strong>, with no units.'))
answer(27,p('Expected result for the same surfaces: F<sub>fr</sub> = μ<sub>k</sub>N and N = F<sub>g</sub>, so doubling, tripling, or quadrupling the weight approximately doubles, triples, or quadruples kinetic friction. Compare this prediction with your measured ratios.'))
answer(28,p('Fit a line to your measured F<sub>fr</sub> versus F<sub>g</sub> data. The ideal relationship is <strong>F<sub>fr</sub> = μ<sub>k</sub>F<sub>g</sub></strong>, where both forces are in newtons and the slope μ<sub>k</sub> is dimensionless.','Use your own numerical slope; no measurements are supplied. A nonzero fitted intercept can indicate balance zero error or additional resistance.'))
answer(29,p('<strong>Your measurements are required.</strong> Calculate μ<sub>k</sub> = ΔF<sub>fr</sub>/ΔF<sub>g</sub> from two well-separated points on the best-fit line. Both numerator and denominator are in newtons, so the coefficient has no units.'))
answer(30,parts('Low friction: bearings in machinery, ski bases sliding on snow, and lubricated engine parts.','High friction: shoe soles gripping the ground, bicycle brakes, and vehicle tires gripping the road.'))
answer(31,p('Repeat the steady-speed pulling measurements on a different horizontal surface while controlling the blocks, pulling direction, and speed. Plot F<sub>fr</sub> against total weight and determine the new slope μ<sub>k</sub>. Compare slopes; do not invent a numerical result without measurements.'))
answer(32,p('For the same total weight and the same dry surfaces, kinetic friction should be <strong>approximately independent of apparent contact area</strong>. In the model F<sub>fr</sub> = μ<sub>k</sub>N, neither μ<sub>k</sub> nor N changes when the blocks are rearranged. State whether your results support that prediction within measurement uncertainty.'))
answer(33,p('Possible errors include an incorrectly zeroed spring balance, changing pulling speed, a string angled upward (reducing N), rough or dirty patches, different block surfaces, and reading the force while starting rather than sliding steadily.','Repeat trials, keep the pull horizontal, measure at steady speed, and report the variation among readings.'))
answer(34,parts('Reduce friction in wheel bearings, pedal bearings, and the chain using lubrication and well-adjusted bearings.','Friction is needed between tires and the road and between brake pads and the braking surface. It also helps keep your feet on the pedals.'))
answer(35,parts('The coefficient of kinetic friction is <strong>μ<sub>k</sub> = F<sub>fr</sub>/N</strong>, the ratio of sliding friction to normal force for a pair of surfaces.','It has no units because N/N = 1.'))
answer(36,p('At steady speed, F<sub>fr</sub> = 120 N. On a level road with horizontal push, N = 250 N.','μ<sub>k</sub> = 120/250 = <strong>0.48</strong>.'))
answer(37,p('At steady speed, F<sub>fr</sub> = 24.5 N. N = F<sub>fr</sub>/μ<sub>k</sub> = 24.5/0.0100 = <strong>2.45 × 10³ N</strong>. This is the block’s weight under the stated horizontal conditions.'))
answer(38,p('The weight and surfaces are unchanged, so the friction model predicts the same pulling force: <strong>0.10 N</strong>. Doubling the apparent contact area does not double friction.'))
answer(39,p('N = 48 N and steady-speed friction is 42 N. Thus μ<sub>k</sub> = 42/48 = <strong>0.88</strong>.'))
answer(40,p('Measure the unstretched hanging length L₀, then the length L₁ with mass m₁. The extension is x₁ = L₁ − L₀. If the rubber band approximately follows Hooke’s law over this range, predict <strong>x₂ = x₁(m₂/m₁)</strong> and <strong>x₃ = x₁(m₃/m₁)</strong>.','Predicted total lengths are L₀ + x₂ and L₀ + x₃. Rubber bands need not be linear, so compare your measured extensions with the predictions rather than assuming they agree.'))
answer(41,p('<strong>The source omits the units of k, so a unique numerical force cannot be determined.</strong> Use F = kx with consistent length units.','If the intended k is 3.2 N/cm, F = (3.2)(20) = <strong>64 N</strong>. If k is 3.2 N/m, convert 20 cm to 0.20 m: F = (3.2)(0.20) = <strong>0.64 N</strong>. The chapter’s graphs use centimetres, suggesting the first interpretation.'))
answer(42,p('From Figure 3.3.1, a 1.0 N load produces 0.75 cm extension.','k = ΔF/Δx = 1.0/0.75 = <strong>1.33 N/cm ≈ 133 N/m</strong>. The graph’s slope has units; it is not dimensionless.'))
answer(43,p('For the same spring within its elastic range, extension is proportional to weight and therefore mass.','x₂ = x₁(m₂/m₁) = (10 cm)(5.0/2.5) = <strong>20 cm</strong>.'))
answer(44,parts('Your force-versus-depression equation is <strong>F = kx</strong>, with k determined from the measured slope ΔF/Δx. If F is in newtons and x in centimetres, k is in N/cm. No numerical depression data are supplied.','If your graph is straight and passes through the origin within uncertainty, F is directly proportional to x. A straight line with a nonzero intercept is linear but is not a direct proportion.'))
answer(45,p('<strong>Your two measured forces are required.</strong> If neither method is treated as the accepted reference, percent difference = 100|F<sub>graph</sub> − F<sub>balance</sub>| / [(F<sub>graph</sub> + F<sub>balance</sub>)/2].','For example, 2.00 N and 2.10 N would give 4.88%, but these example values are not your experimental result. If the balance is specified as a reference, use percent error relative to that balance reading instead.'))
answer(46,p('Clamp the strip securely, establish its unloaded position, and add known masses to mark the corresponding deflections in grams. Use several loads to test whether the scale spacing is linear, and stay within the elastic range.','If F = kx with x in metres, then m = kx/g in kilograms, or <strong>m = 1000kx/g</strong> in grams. Check the scale with an additional known mass before using it to weigh letters.'))
answer(47,p('<strong>The premise is a source error: the spring constant does have units.</strong> From F = kx, k = F/x, so its SI unit is <strong>N/m</strong>. On a graph with extension in centimetres, the slope is in N/cm. A coefficient of friction is dimensionless; a spring constant is not.'))
answer(48,p('Using Figure 3.3.1, k = 1.0 N/0.75 cm ≈ 1.33 N/cm.','<strong>F = (1.33 N/cm)x</strong> when x is measured in centimetres, or <strong>F = (133 N/m)x</strong> when x is in metres.'))
answer(49,parts('x = F/k = 4.0/(1.0/0.75) = <strong>3.0 cm</strong>.','F = kx = (1.0/0.75)(2.0) = <strong>2.7 N</strong> (2.67 N before rounding).'))
answer(50,p('At F = 5.0 N, the graph gives x ≈ 3.75 cm. The spring constant is <strong>k = F/x ≈ 5.0/3.75 = 1.33 N/cm ≈ 133 N/m</strong>.','The source reverses the ratio: x/F = 0.75 cm/N is the compliance, the reciprocal of the spring constant.'))
answer(51,parts('Slope = (100 N − 0)/(5.0 cm − 0) = <strong>20 N/cm = 2000 N/m</strong>.','<strong>F<sub>g</sub> = (20 N/cm)x</strong>, with x in centimetres.','x = 80.0/20 = <strong>4.0 cm</strong>.','F<sub>g</sub> = (20)(3.0) = <strong>60 N</strong>.'))
answer(52,ANSWERS['q-17'])
answer(53,p('Four Earth radii <em>above the surface</em> means r = R + 4R = 5R from the centre.','F′ = F(R/r)² = 2500/5² = <strong>100 N</strong>.'))
